    55  static void ptls_base64_cell(const uint8_t *data, char *text)
    56  {
    57      int n[4];
    58
    59      n[0] = data[0] >> 2;
    60      n[1] = ((data[0] & 3) << 4) | (data[1] >> 4);
    61      n[2] = ((data[1] & 15) << 2) | (data[2] >> 6);
    62      n[3] = data[2] & 63;
    63
    64      for (int i = 0; i < 4; i++) {
    65          text[i] = ptls_base64_alphabet[n[i]];
    66      }
    67  }
