    74  int ptls_base64_encode(const uint8_t *data, size_t data_len, char *ptls_base64_text)
    75  {
    76      int l = 0;
    77      int lt = 0;
    78
    79      while ((data_len - l) >= 3) {
    80          ptls_base64_cell(data + l, ptls_base64_text + lt);
    81          l += 3;
    82          lt += 4;
    83      }
    84
    85      switch (data_len - l) {
    86      case 0:
    87          break;
    88      case 1:
    89          ptls_base64_text[lt++] = ptls_base64_alphabet[data[l] >> 2];
    90          ptls_base64_text[lt++] = ptls_base64_alphabet[(data[l] & 3) << 4];
    91          ptls_base64_text[lt++] = '=';
    92          ptls_base64_text[lt++] = '=';
    93          break;
    94      case 2:
    95          ptls_base64_text[lt++] = ptls_base64_alphabet[data[l] >> 2];
    96          ptls_base64_text[lt++] = ptls_base64_alphabet[((data[l] & 3) << 4) | (data[l + 1] >> 4)];
    97          ptls_base64_text[lt++] = ptls_base64_alphabet[((data[l + 1] & 15) << 2)];
    98          ptls_base64_text[lt++] = '=';
    99          break;
   100      default:
   101          break;
   102      }
   103      ptls_base64_text[lt++] = 0;
   104
   105      return lt;
   106  }
