   108  /*
   109   * Take into input a line of text, so as to work by increments.
   110   * The intermediate text of the decoding is kept in a state variable.
   111   * The decoded data is accumulated in a PTLS buffer.
   112   * The parsing is consistent with the lax definition in RFC 7468
   113   */
   114
   115  void ptls_base64_decode_init(ptls_base64_decode_state_t *state)
   116  {
   117      state->nbc = 0;
   118      state->nbo = 3;
   119      state->v = 0;
   120      state->status = PTLS_BASE64_DECODE_IN_PROGRESS;
   121  }
   122
   123  int ptls_base64_decode(const char *text, ptls_base64_decode_state_t *state, ptls_buffer_t *buf)
   124  {
   125      int ret = 0;
   126      uint8_t decoded[3];
   127      size_t text_index = 0;
   128      int c;
   129      signed char vc;
   130
   131      /* skip initial blanks */
   132      while (text[text_index] != 0) {
   133          c = text[text_index];
   134
   135          if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
   136              text_index++;
   137          } else {
   138              break;
   139          }
   140      }
   141
   142      while (text[text_index] != 0 && ret == 0 && state->status == PTLS_BASE64_DECODE_IN_PROGRESS) {
   143          c = text[text_index++];
   144
   145          vc = 0 < c && c < 0x7f ? ptls_base64_values[c] : -1;
   146          if (vc == -1) {
   147              if (state->nbc == 2 && c == '=' && text[text_index] == '=') {
   148                  state->nbc = 4;
   149                  text_index++;
   150                  state->nbo = 1;
   151                  state->v <<= 12;
   152              } else if (state->nbc == 3 && c == '=') {
   153                  state->nbc = 4;
   154                  state->nbo = 2;
   155                  state->v <<= 6;
   156              } else {
   157                  /* Skip final blanks */
   158                  for (--text_index; text[text_index] != 0; ++text_index) {
   159                      c = text[text_index];
   160                      if (!(c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == 0x0B || c == 0x0C))
   161                          break;
   162                  }
   163
   164                  /* Should now be at end of buffer */
   165                  if (text[text_index] == 0) {
   166                      break;
   167                  } else {
   168                      /* Not at end of buffer, signal a decoding error */
   169                      state->nbo = 0;
   170                      state->status = PTLS_BASE64_DECODE_FAILED;
   171                      ret = PTLS_ERROR_INCORRECT_BASE64;
   172                  }
   173              }
   174          } else {
   175              state->nbc++;
   176              state->v <<= 6;
   177              state->v |= vc;
   178          }
   179
   180          if (ret == 0 && state->nbc == 4) {
   181              /* Convert to up to 3 octets */
   182              for (int j = 0; j < state->nbo; j++) {
   183                  decoded[j] = (uint8_t)(state->v >> (8 * (2 - j)));
   184              }
   185
   186              ret = ptls_buffer__do_pushv(buf, decoded, state->nbo);
   187
   188              if (ret == 0) {
   189                  /* test for fin or continuation */
   190                  if (state->nbo < 3) {
   191                      /* Check that there are only trainling blanks on this line */
   192                      while (text[text_index] != 0) {
   193                          c = text[text_index++];
   194
   195                          if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == 0x0B || c == 0x0C) {
   196                              continue;
   197                          }
   198                      }
   199                      if (text[text_index] == 0) {
   200                          state->status = PTLS_BASE64_DECODE_DONE;
   201                      } else {
   202                          state->status = PTLS_BASE64_DECODE_FAILED;
   203                          ret = PTLS_ERROR_INCORRECT_BASE64;
   204                      }
   205                      break;
   206                  } else {
   207                      state->v = 0;
   208                      state->nbo = 3;
   209                      state->nbc = 0;
   210                  }
   211              }
   212          }
   213      }
   214      return ret;
   215  }
