   268  static int ptls_get_pem_object(FILE *F, const char *label, ptls_buffer_t *buf)
   269  {
   270      int ret = PTLS_ERROR_PEM_LABEL_NOT_FOUND;
   271      char line[256];
   272      ptls_base64_decode_state_t state;
   273
   274      /* Get the label on a line by itself */
   275      while (fgets(line, 256, F)) {
   276          if (ptls_compare_separator_line(line, "BEGIN", label) == 0) {
   277              ret = 0;
   278              ptls_base64_decode_init(&state);
   279              break;
   280          }
   281      }
   282      /* Get the data in the buffer */
   283      while (ret == 0 && fgets(line, 256, F)) {
   284          if (ptls_compare_separator_line(line, "END", label) == 0) {
   285              if (state.status == PTLS_BASE64_DECODE_DONE || (state.status == PTLS_BASE64_DECODE_IN_PROGRESS && state.nbc == 0)) {
   286                  ret = 0;
   287              } else {
   288                  ret = PTLS_ERROR_INCORRECT_BASE64;
   289              }
   290              break;
   291          } else {
   292              ret = ptls_base64_decode(line, &state, buf);
   293          }
   294      }
   295
   296      return ret;
   297  }
