   299  int ptls_load_pem_objects(char const *pem_fname, const char *label, ptls_iovec_t *list, size_t list_max, size_t *nb_objects)
   300  {
   301      FILE *F;
   302      int ret = 0;
   303      size_t count = 0;
   304  #ifdef _WINDOWS
   305      errno_t err = fopen_s(&F, pem_fname, "r");
   306      if (err != 0) {
   307          ret = -1;
   308      }
   309  #else
   310      F = fopen(pem_fname, "r");
   311      if (F == NULL) {
   312          ret = -1;
   313      }
   314  #endif
   315
   316      *nb_objects = 0;
   317
   318      if (ret == 0) {
   319          while (count < list_max) {
   320              ptls_buffer_t buf;
   321
   322              ptls_buffer_init(&buf, "", 0);
   323
   324              ret = ptls_get_pem_object(F, label, &buf);
   325
   326              if (ret == 0) {
   327                  if (buf.off > 0 && buf.is_allocated) {
   328                      list[count].base = buf.base;
   329                      list[count].len = buf.off;
   330                      count++;
   331                  } else {
   332                      ptls_buffer_dispose(&buf);
   333                  }
   334              } else {
   335                  ptls_buffer_dispose(&buf);
   336                  break;
   337              }
   338          }
   339      }
   340
   341      if (ret == PTLS_ERROR_PEM_LABEL_NOT_FOUND && count > 0) {
   342          ret = 0;
   343      }
   344
   345      *nb_objects = count;
   346
   347      if (F != NULL) {
   348          fclose(F);
   349      }
   350
   351      return ret;
   352  }
