   354  #define PTLS_MAX_CERTS_IN_CONTEXT 16
   355
   356  int ptls_load_certificates(ptls_context_t *ctx, char const *cert_pem_file)
   357  {
   358      int ret = 0;
   359
   360      ctx->certificates.list = (ptls_iovec_t *)malloc(PTLS_MAX_CERTS_IN_CONTEXT * sizeof(ptls_iovec_t));
   361
   362      if (ctx->certificates.list == NULL) {
   363          ret = PTLS_ERROR_NO_MEMORY;
   364      } else {
   365          ret = ptls_load_pem_objects(cert_pem_file, "CERTIFICATE", ctx->certificates.list, PTLS_MAX_CERTS_IN_CONTEXT,
   366                                      &ctx->certificates.count);
   367      }
   368
   369      return ret;
   370  }
