    81  size_t ptls_asn1_read_type(const uint8_t *bytes, size_t bytes_max, int *structure_bit, int *type_class, uint32_t *type_number,
    82                             int *decode_error, int level, ptls_minicrypto_log_ctx_t *log_ctx)
    83  {
    84      /* Get the type byte */
    85      size_t byte_index = 1;
    86      uint8_t first_byte = bytes[0];
    87      *structure_bit = (first_byte >> 5) & 1;
    88      *type_class = (first_byte >> 6) & 3;
    89      *type_number = first_byte & 31;
    90
    91      if (*type_number == 31) {
    92          uint32_t long_type = 0;
    93          const uint32_t type_number_limit = 0x07FFFFFFF;
    94          int next_byte;
    95          int end_found = 0;
    96
    97          while (byte_index < bytes_max && long_type <= type_number_limit) {
    98              next_byte = bytes[byte_index++];
    99              long_type <<= 7;
   100              long_type |= next_byte & 127;
   101              if ((next_byte & 128) == 0) {
   102                  end_found = 1;
   103                  break;
   104              }
   105          }
   106
   107          if (end_found) {
   108              *type_number = long_type;
   109          } else {
   110              /* This is an error */
   111              byte_index = ptls_asn1_error_message("Incorrect type coding", bytes_max, byte_index, level, log_ctx);
   112              *decode_error = PTLS_ERROR_BER_MALFORMED_TYPE;
   113          }
   114      }
   115
   116      return byte_index;
   117  }
