   207  size_t ptls_asn1_validation_recursive(const uint8_t *bytes, size_t bytes_max, int *decode_error, int level,
   208                                        ptls_minicrypto_log_ctx_t *log_ctx)
   209  {
   210      /* Get the type byte */
   211      int structure_bit = 0;
   212      int type_class = 0;
   213      uint32_t type_number = 0;
   214      uint32_t length = 0;
   215      int indefinite_length = 0;
   216      size_t last_byte = 0;
   217      /* Decode the type */
   218      size_t byte_index =
   219          ptls_asn1_read_type(bytes, bytes_max, &structure_bit, &type_class, &type_number, decode_error, level, log_ctx);
   220
   221      if (*decode_error == 0 && log_ctx != NULL) {
   222          ptls_asn1_print_type(type_class, type_number, level, log_ctx);
   223      }
   224
   225      /* Get the length */
   226      byte_index =
   227          ptls_asn1_read_length(bytes, bytes_max, byte_index, &length, &indefinite_length, &last_byte, decode_error, level, log_ctx);
   228
   229      if (last_byte <= bytes_max) {
   230          if (structure_bit) {
   231              /* If structured, recurse on a loop */
   232              if (log_ctx != NULL) {
   233                  log_ctx->fn(log_ctx->ctx, " {\n");
   234              }
   235
   236              while (byte_index < last_byte) {
   237                  if (indefinite_length != 0 && bytes[byte_index] == 0) {
   238                      if (byte_index + 2 > bytes_max || bytes[byte_index + 1] != 0) {
   239                          byte_index =
   240                              ptls_asn1_error_message("EOC: unexpected end of content", bytes_max, byte_index, level + 1, log_ctx);
   241
   242                          *decode_error = PTLS_ERROR_BER_UNEXPECTED_EOC;
   243                          byte_index = bytes_max;
   244                          break;
   245                      } else {
   246                          if (log_ctx != NULL) {
   247                              ptls_asn1_print_indent(level, log_ctx);
   248                              log_ctx->fn(log_ctx->ctx, "EOC\n");
   249                          }
   250                          byte_index += 2;
   251                          break;
   252                      }
   253                  } else {
   254                      byte_index += ptls_asn1_validation_recursive(bytes + byte_index, last_byte - byte_index, decode_error,
   255                                                                   level + 1, log_ctx);
   256
   257                      if (*decode_error) {
   258                          byte_index = bytes_max;
   259                          break;
   260                      }
